<template>
  <nav
    class="w3-sidebar w3-bar-block w3-collapse w3-theme-l5 w3-animate-left app-sidebar"
    :style="sidebarStyle"
  >
    <button
      type="button"
      class="sidebar-close-btn w3-hide-large"
      aria-label="Đóng menu"
      title="Đóng menu"
      @click="$emit('close')"
    >
      ×
    </button>

    <h4 class="w3-bar-item sidebar-title">
      Menu
    </h4>

    <template v-for="item in visibleMenuItems">
      <!-- Menu thường -->
      <router-link
        v-if="!item.children"
        :key="item.id || menuLabel(item)"
        :to="menuPath(item)"
        class="w3-bar-item w3-button w3-hover-black sidebar-menu-item"
        @click.native="closeOnMobile"
      >
        <b-icon
          :icon="item.icon"
          class="sidebar-menu-icon"
          aria-hidden="true"
        />
        <span>{{ menuLabel(item) }}</span>
      </router-link>

      <!-- Menu có submenu -->
      <div
        v-else
        :key="item.id || menuLabel(item)"
        class="sidebar-menu-group"
      >
        <button
          type="button"
          class="w3-bar-item w3-button w3-hover-black sidebar-menu-item submenu-parent"
          :class="{ 'submenu-parent-active': hasActiveChild(item) }"
          @click="toggleSubmenu(menuKey(item))"
        >
          <b-icon
            :icon="item.icon"
            class="sidebar-menu-icon"
            aria-hidden="true"
          />

          <span class="submenu-text">
            {{ menuLabel(item) }}
          </span>

          <b-icon
            :icon="isOpen(menuKey(item)) ? 'chevron-down' : 'chevron-right'"
            class="submenu-arrow"
            aria-hidden="true"
          />
        </button>

        <div
          v-show="isOpen(menuKey(item))"
          class="submenu"
        >
          <router-link
            v-for="child in visibleChildren(item)"
            :key="child.id || menuLabel(child)"
            :to="menuPath(child, item)"
            class="w3-bar-item w3-button w3-hover-black submenu-item"
            @click.native="closeOnMobile"
          >
            <b-icon
              :icon="child.icon || 'circle'"
              class="submenu-icon"
              aria-hidden="true"
            />
            <span>{{ menuLabel(child) }}</span>
          </router-link>
        </div>
      </div>
    </template>
  </nav>
</template>

<script>
import menuItems from '@/config/menu'
import { getMenuLabel, getMenuPath } from '@/config/menuRoute'
import { getMockAccessLevel, canViewMenu } from '@/config/menuPermission'

export default {
  name: 'AppSidebar',

  props: {
    open: {
      type: Boolean,
      default: false
    }
  },

  data() {
    return {
      menuItems,
      openMenus: {},
      accessLevel: getMockAccessLevel()
    }
  },

  computed: {
    sidebarStyle() {
      return this.open ? { display: 'block' } : {}
    },

    visibleMenuItems() {
      return this.menuItems.filter(item => {
        return !this.isHidden(item) && this.canView(item) &&
          (!item.children || this.visibleChildren(item).length > 0)
      })
    }
  },

  created() {
    this.refreshAccessLevel()
    this.openCurrentMenu()
  },

  watch: {
    '$route.path'() {
      this.refreshAccessLevel()
      this.openCurrentMenu()
    }
  },

  methods: {
    refreshAccessLevel() {
      this.accessLevel = getMockAccessLevel()
    },

    canView(item) {
      return canViewMenu(item, this.accessLevel)
    },

    menuLabel(item) {
      return getMenuLabel(item)
    },

    menuKey(item) {
      return item && item.id != null
        ? String(item.id)
        : this.menuLabel(item)
    },

    isHidden(item) {
      return !!(
        item && (
          item.hidden ||
          (item.meta && item.meta.hidden)
        )
      )
    },

    visibleChildren(item) {
      return (item.children || []).filter(child => !this.isHidden(child) && this.canView(child))
    },

    toggleSubmenu(name) {
      this.$set(
        this.openMenus,
        name,
        !this.openMenus[name]
      )
    },

    isOpen(name) {
      return !!this.openMenus[name]
    },

    menuPath(item, parent = null) {
      const parentPath = parent
        ? getMenuPath(parent)
        : ''

      return getMenuPath(item, parentPath)
    },

    routeMatches(routePath) {
      if (this.$route.path === routePath) return true

      return (this.$route.matched || []).some(record => {
        return record.path === routePath
      })
    },

    hasActiveChild(item) {
      if (!item || !item.children) return false

      return item.children.some(child => {
        return this.routeMatches(this.menuPath(child, item))
      })
    },

    openCurrentMenu() {
      this.menuItems.forEach(item => {
        if (!item.children) return

        if (this.hasActiveChild(item)) {
          this.$set(this.openMenus, this.menuKey(item), true)
        }
      })
    },

    closeOnMobile() {
      if (window.innerWidth <= 992) {
        this.$emit('close')
      }
    }
  }
}
</script>
