// Phân quyền giao diện DEMO, không thay thế xác thực từ API.
export function getMockAccessLevel() {
  try {
    const user = JSON.parse(sessionStorage.getItem('mockUser') || 'null')
    return user && user.isActive === true ? Number(user.accessLevel) || 0 : 0
  } catch (error) {
    return 0
  }
}

export function canViewMenu(item, accessLevel) {
  const requiredAuth = Number((item.meta && item.meta.auth) || 0)
  return requiredAuth === 0 || accessLevel >= requiredAuth
}
