import Vue from 'vue'
import VueRouter from 'vue-router'
import menuItems from '@/config/menu'
import { buildRoutes } from '@/config/menuRoute'
import { getMockAccessLevel, canViewMenu } from '@/config/menuPermission'

Vue.use(VueRouter)

// Route được sinh tự động từ src/config/menu.js.
// Không cần khai báo lại path/name/component ở đây.
const routes = [
  ...buildRoutes(menuItems),
  { path: '*', redirect: '/' }
]

const router = new VueRouter({
  mode: 'hash',
  routes
})

// Chặn URL trực tiếp vào trang yêu cầu quyền (chỉ demo trên frontend).
router.beforeEach((to, from, next) => {
  const accessLevel = getMockAccessLevel()
  // /Admin là route mặc định của Môn Toán (auth 9).
  // Với quyền 1..8, chuyển đến trang Môn Lý thay vì mở trang bị cấm.
  if (to.path === '/Admin' && accessLevel >= 1 && accessLevel < 9) {
    return next({ path: '/Admin/Ly', replace: true })
  }
  const blocked = to.matched.some(record => !canViewMenu(record, accessLevel))
  if (!blocked) return next()

  if (accessLevel === 0) {
    return next({ path: '/Login', query: { redirect: to.fullPath } })
  }
  return next('/')
})

export default router
