<template>
  <div class="w3-top">
    <nav class="w3-flex w3-theme top-nav">
      <router-link to="/" class="w3-button w3-theme-l1 app-brand">My App</router-link>

      <div class="w3-flex w3-hide-small">
        <router-link to="/" class="w3-button w3-hover-white">Home</router-link>
        <router-link to="/dashboard" class="w3-button w3-hover-white">Dashboard</router-link>
        <router-link to="/users" class="w3-button w3-hover-white">Users</router-link>
      </div>

      <div class="navbar-spacer"></div>
      <div class="user-area" ref="userArea">
        <router-link v-if="!user" to="/Login" class="w3-button w3-hover-white">
          <b-icon icon="box-arrow-in-right" aria-hidden="true" /> Login
        </router-link>
        <template v-else>
          <button type="button" class="w3-button user-trigger" :aria-expanded="showUserMenu ? 'true' : 'false'"
                  aria-haspopup="true" @click="showUserMenu = !showUserMenu">
            <b-icon icon="person-circle" aria-hidden="true" />
            <span class="user-name">{{ user.fullName || user.username }}</span>
            <b-icon :icon="showUserMenu ? 'chevron-up' : 'chevron-down'" aria-hidden="true" />
          </button>
          <div v-if="showUserMenu" class="user-dropdown" role="menu">
            <div class="user-dropdown-title"><b-icon icon="person-circle" /> Thông tin tài khoản</div>
            <div class="user-detail"><span>Tài khoản</span><strong>{{ user.username }}</strong></div>
            <div class="user-detail"><span>Họ tên</span><strong>{{ user.fullName || '-' }}</strong></div>
            <div class="user-detail"><span>Quyền</span><strong>{{ user.accessLevel }}</strong></div>
            <div class="user-detail"><span>Email</span><strong class="email-value">{{ user.email || '-' }}</strong></div>
            <button type="button" class="logout-btn" role="menuitem" @click="logout">
              <b-icon icon="box-arrow-right" /> Đăng xuất
            </button>
          </div>
        </template>
      </div>
      <button type="button" class="w3-button w3-hide-large w3-theme-l1 mobile-menu-toggle"
              title="Mở menu" @click="$emit('toggle-sidebar')">
        <b-icon icon="list" aria-hidden="true" />
      </button>
    </nav>
  </div>
</template>

<script>
export default {
  name: 'AppNavbar',
  props: { user: { type: Object, default: null } },
  data() { return { showUserMenu: false } },
  watch: { '$route.path'() { this.showUserMenu = false } },
  mounted() { document.addEventListener('click', this.onOutsideClick) },
  beforeDestroy() { document.removeEventListener('click', this.onOutsideClick) },
  methods: {
    onOutsideClick(event) {
      if (this.$refs.userArea && !this.$refs.userArea.contains(event.target)) this.showUserMenu = false
    },
    logout() {
      this.showUserMenu = false
      this.$emit('logout')
    }
  }
}
</script>

