.navbar-spacer { flex: 1; }
.user-area { position: relative; z-index: 1100; }
.user-trigger { display: flex; align-items: center; gap: 7px; color: #fff; white-space: nowrap; }
.user-name { max-width: 160px; overflow: hidden; text-overflow: ellipsis; }
.user-dropdown {
  position: absolute; top: 100%; right: 0; width: 280px;
  padding: 12px; color: #222; background: #fff;
  border: 1px solid #ddd; border-radius: 4px;
  box-shadow: 0 5px 18px rgba(0,0,0,.20);
  font-size: 13px;
}
.user-dropdown-title { font-weight: bold; margin-bottom: 10px; }
.user-detail { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; padding: 5px 0; }
.user-detail span { color: #666; flex-shrink: 0; }
.user-detail strong { text-align: right; overflow-wrap: anywhere; }
.email-value { font-size: 12px; }
.logout-btn { display: block; width: 100%; margin-top: 10px; padding: 8px; border: 0; border-top: 1px solid #ddd; color: #b42318; background: #fff; text-align: left; cursor: pointer; }
.logout-btn:hover { background: #f5f5f5; }
.mobile-menu-toggle { margin-left: 0; }
