<template>
  <div>
    <AppNavbar v-if="!isLoginPage" :user="currentUser" @logout="logout" @toggle-sidebar="sidebarOpen = true" />
    <AppSidebar v-if="!isLoginPage" :open="sidebarOpen" @close="sidebarOpen = false" />

    <div
      v-if="sidebarOpen && !isLoginPage"
      class="w3-overlay w3-hide-large sidebar-overlay"
      style="display: block"
      title="Đóng menu"
      @click="sidebarOpen = false"
    />

    <main :class="isLoginPage ? '' : 'w3-main app-main'">
      <div :class="isLoginPage ? '' : 'app-content'"><router-view /></div>
      <AppFooter v-if="!isLoginPage" />
    </main>
  </div>
</template>

<script>
import AppNavbar from '@/components/AppNavbar.vue'
import AppSidebar from '@/components/AppSidebar.vue'
import AppFooter from '@/components/AppFooter.vue'

export default {
  name: 'App',
  components: { AppNavbar, AppSidebar, AppFooter },
  data: () => ({ sidebarOpen: false, currentUser: null }),
  created() {
    this.refreshUser()
    this.$root.$on('mock-auth-changed', this.refreshUser)
  },
  beforeDestroy() {
    this.$root.$off('mock-auth-changed', this.refreshUser)
  },
  methods: {
    refreshUser() {
      try {
        const user = JSON.parse(sessionStorage.getItem('mockUser') || 'null')
        this.currentUser = user && user.isActive === true ? user : null
      } catch (error) {
        this.currentUser = null
      }
    },
    logout() {
      sessionStorage.removeItem('mockUser')
      this.refreshUser()
      this.$root.$emit('mock-auth-changed')
      this.sidebarOpen = false
      this.$router.push('/Login')
    }
  },
  computed: {
    isLoginPage() { return this.$route.path.toLowerCase() === '/login' }
  }
}
</script>
